mapper.select:
SELECT
gt.id, gt.gripper_id, gt.task_type, gt.task_status,
gt.container_unit_id, gt.created_time, gt.completed_time,
cm.alias_code, cm.container_type
FROM gripper_task gt
LEFT JOIN container_main cm ON gt.container_unit_id = cm.id
WHERE 1 = 1

    AND gt.gripper_id = #{gripperId}


    AND gt.task_status = #{taskStatus}


    AND gt.created_time  >=  #{createdAfter}


    AND gt.created_time  <=  #{createdBefore}

ORDER BY gt.created_time DESC
